SELECT EXISTS (
  SELECT 1
  FROM msf_usr_app_info
  WHERE user_id = #{userId}
    AND uuid = #{deviceUuid}
    AND bio_login_yn = 'Y'
    AND apv_sttus_cd = 'A'
)

SELECT EXISTS (
  SELECT 1
  FROM msf_usr_app_info
  WHERE user_id = #{userId}
    AND uuid = #{deviceUuid}
    AND bio_login_token = #{bioKey}
    AND bio_login_yn = 'Y'
    AND apv_sttus_cd = 'A'
)

mapper.update:
UPDATE msf_user_info SET
user_sttus_cd = #{userStatusCode}, access_limit_yn = 'Y', access_limit_dt = now(), chg_dt = now(), pwd_chg_yn = 'N',
login_chk_cnt = login_chk_cnt + 1 WHERE user_id = #{userId}

UPDATE msf_usr_app_info
SET last_access_dt = now()
WHERE user_id = #{userId}
  AND uuid = #{deviceUuid}
  AND apv_sttus_cd = 'A'
